import { useEffect, useState } from 'react'
import type { Project, Scenario } from '../../../shared/types'
import { StatusGlyph } from './ScenariosView'

function Diff({ text }: { text: string }): React.JSX.Element {
  return (
    <pre className="diff">
      {text.split('\n').map((line, i) => (
        <div key={i} className={line.startsWith('+') && !line.startsWith('+++') ? 'add' : line.startsWith('-') && !line.startsWith('---') ? 'del' : ''}>
          {line || ' '}
        </div>
      ))}
    </pre>
  )
}

export default function ScenarioDetail({ project, scenario: s, onClose }: { project: Project; scenario: Scenario; onClose: () => void }): React.JSX.Element {
  const [shot, setShot] = useState<string | null>(null)

  useEffect(() => {
    setShot(null)
    if (s.finding?.screenshot) void window.api.imageData(project.id, s.finding.screenshot).then(setShot)
  }, [project.id, s.finding?.screenshot])

  return (
    <aside className="detail" aria-label={`Scenario ${s.id}`}>
      <header>
        <StatusGlyph status={s.status} />
        <h3>
          {s.id} {s.title}
        </h3>
        <button className="close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </header>
      <dl>
        <dt>Priority</dt>
        <dd className={`prio ${s.priority}`}>{s.priority}</dd>
        <dt>Journey</dt>
        <dd>{s.journey}</dd>
import { useEffect, useState } from 'react'
import type { Project } from '../../shared/types'
import Sidebar from './components/Sidebar'
import ChatView from './components/ChatView'
import ScenariosView from './components/ScenariosView'
import SettingsView from './components/SettingsView'

export type View = 'chat' | 'scenarios' | 'settings'

const BUSY_PHASES = new Set(['cloning', 'inventory', 'scenarios', 'bootstrapping', 'sweeping'])
export const isWorking = (p?: Project): boolean => Boolean(p && BUSY_PHASES.has(p.phase))

function App(): React.JSX.Element {
  const [projects, setProjects] = useState<Project[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [view, setView] = useState<View>('chat')

  useEffect(() => {
    void window.api.listProjects().then(setProjects)
    return window.api.onEvent((event) => {
      setProjects((prev) => {
        if (event.type === 'project') {
          const exists = prev.some((p) => p.id === event.project.id)
          return exists ? prev.map((p) => (p.id === event.project.id ? event.project : p)) : [event.project, ...prev]
        }
